 const sites=Array.from({length:5},(_,i)=>({id:'S'+i,name:['中心广场','东区车站','西区公园','北区路口','南区商场'][i],region:['中心区','东区','西区','北区','南区'][i],address:'示例路'+(i+1)+'号'}));
