 const captures=types.flatMap((type,t)=>Array.from({length:18},(_,i)=>({id:`C${t}-${i}`,type,target:type==='电围'?'46000000000'+String(i%6).padStart(4,'0'):type==='车牌'?'示A'+(10000+i%6):type==='MAC'?'02:00:00:00:00:'+String(i%6).padStart(2,'0'):'人像-'+(i%6+1),imei:'86000000000'+String(i%6).padStart(4,'0'),site:sites[i%5].name,region:sites[i%5].region,device:devices[i%10].name,deviceId:devices[i%10].id,time:`2026-10-0${5+Math.floor(i/6)} ${String(8+Math.floor(i/6)).padStart(2,'0')}:${String(i%6*9).padStart(2,'0')}:00`,person:'P'+i%6,score:[100,92,78,61,35,12][i%6]})));
