function enter(){const account=document.getElementById('account').value.trim(),password=document.getElementById('password').value;const u=db.users.find(x=>x.account===account&&x.password===password);if(!u||!u.enabled){document.getElementById('login-error').textContent=u?'此用户已禁用':'账号或密码错误';return}session=u.id;document.getElementById('login').style.display='none';document.getElementById('shell').style.display='block';active='系统首页';log('登录');render()}
