function modal(title,body,onSave,submit='保存'){modalPrevious=document.activeElement;modalSave=onSave;const el=document.getElementById('modal-host');el.innerHTML=`<div class="modal-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal"><header><h2 id="modal-title">${E(title)}</h2>${B('关闭','close-modal')}</header><form id="modal-form">${body}<div class="form-error" role="alert" id="form-error"></div><footer>${B('取消','close-modal')}${onSave?`<button class="btn primary" type="submit">${E(submit)}</button>`:''}</footer></form></section></div>`;el.querySelector('input,select,textarea,button')?.focus()}
function closeModal(){document.getElementById('modal-host').innerHTML='';modalSave=null;modalPrevious?.focus();modalPrevious=null}
function formError(s){const el=document.getElementById('form-error');el.style.display='block';el.textContent=s}
function field(name,label,value='',options=null,type='text',required=false){return `<label>${E(label)}${options?`<select name="${name}">${options.map(o=>{const v=typeof o==='object'?o.value:o,l=typeof o==='object'?o.label:o;return `<option value="${E(v)}" ${v==value?'selected':''}>${E(l)}</option>`}).join('')}</select>`:`<input name="${name}" type="${type}" value="${E(value)}" ${required?'required':''}>`}</label>`}
function checkFields(name,values,selected=[]){return `<div class="checks">${values.map(v=>`<label><input type="checkbox" name="${name}" value="${E(v.value??v)}" ${selected.includes(v.value??v)?'checked':''}>${E(v.label??v)}</label>`).join('')}</div>`}
function controls(fields,label='搜索',extra=''){return `<form class="card toolbar filters" id="query-form"><div class="row">${fields.map(f=>field(f[0],f[1],ps().filters[f[0]]||'',f[2]||null,f[3]||'text')).join('')}<button class="btn primary" type="submit">${label}</button>${B('重置','reset-query')}${extra}</div></form>`}
function filters(rows,bindings){const f=ps().filters;return rows.filter(r=>Object.entries(bindings).every(([k,prop])=>{const v=f[k];if(!v||v==='全部')return true;const val=String(typeof prop==='function'?prop(r):r[prop]??'');if(k==='start')return val.replace(' ','T')>=v;if(k==='end')return val.replace(' ','T')<=v+(v.length===10?'T23:59:59':'');return v.split(/[,，\n]/).some(q=>val.toLowerCase().includes(q.trim().toLowerCase()))}))}
