function table(scope,headers,rows,renderRow,selectable=true,title='数据详情',actions=''){
 scopes[scope]=rows;const sort=ps().sort[scope];let sorted=[...rows];if(sort)sorted.sort((a,b)=>String(a[sort.key]??'').localeCompare(String(b[sort.key]??''),'zh-CN',{numeric:true})*sort.dir);
 const count=sorted.length,max=Math.max(1,Math.ceil(count/ps().limit));ps().page[scope]=Math.min(ps().page[scope]||1,max);const page=ps().page[scope];const slice=sorted.slice((page-1)*ps().limit,page*ps().limit);
 return `<section class="card table-wrap" data-scope="${scope}"><div class="table-title"><h3>${title}</h3><span class="meta">${count} 条</span><div class="right-actions">${actions}</div></div><table><thead><tr>${selectable?`<th><input type="checkbox" aria-label="全选当前结果" data-select-all="${scope}" ${count&&rows.every(r=>selected(scope).includes(r.id))?'checked':''}></th>`:''}${headers.map(h=>`<th>${Array.isArray(h)?`<button data-action="sort" data-args="${scope}|${h[1]}">${h[0]} ↕</button>`:h}</th>`).join('')}</tr></thead><tbody>${slice.map(r=>`<tr data-row-id="${r.id}" data-scope="${scope}" class="${selected(scope).includes(r.id)?'selected':''}">${selectable?`<td><input type="checkbox" data-select="${scope}" value="${r.id}" aria-label="选择 ${E(r.name||r.target||r.id)}" ${selected(scope).includes(r.id)?'checked':''}></td>`:''}${renderRow(r).map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${headers.length+(selectable?1:0)}"><div class="empty">当前条件下无结果 ${B('重置条件','reset-query')}</div></td></tr>`}</tbody></table><div class="pagination"><span>已选 ${rowsSelected(scope).length} 条</span>${B('上一页','page',scope+'|-1','small',page===1)}<span>${page} / ${max}</span>${B('下一页','page',scope+'|1','small',page===max)}<label>每页<select data-limit><option ${ps().limit===5?'selected':''}>5</option><option ${ps().limit===10?'selected':''}>10</option><option ${ps().limit===20?'selected':''}>20</option></select></label></div></section>`
}
const captureRows=(type)=>db.captures.filter(c=>(!type||c.type===type)&&(superuser()||role().sites.includes(c.site)));
