function dataDrawer(){if(!['围栏检索','车牌检索','MAC检索','人像检索','地图研判','伴随任务','碰撞任务','区域统计'].includes(active))return '';return drawer?`<aside class="dataset-drawer"><div class="table-title"><h3>数据集</h3>${B('收起','drawer')}</div>${B('添加当前结果','drawer-add','','primary',!currentDatasetRows().length)}${db.datasets.map(s=>`<div class="dataset-card">${E(s.name)}<p class="meta">${s.items.length} 条</p>${B('查看数据运算','dataset-go',s.id,'small')}</div>`).join('')}${B('进入数据运算','nav','数据运算','primary')}</aside>`:`<button class="dataset-tab" data-action="drawer">数据集 ▸</button>`}
function statsFor(rows,universe=db.captures){const targets=[...new Set(rows.map(r=>r.target))];return targets.map(target=>{const captures=universe.filter(c=>c.target===target);return {id:target,target,count:captures.length,stations:new Set(captures.map(c=>c.site)).size,regions:new Set(captures.map(c=>c.region)).size,first:captures.map(c=>c.time).sort()[0],landing:captures.reduce((acc,c)=>((acc[c.site]=(acc[c.site]||0)+1),acc),{})}})}
