function contextMenu(e,items){e.preventDefault();closeContext();const host=document.getElementById('context-host');host.innerHTML=`<div role="menu" class="context-menu">${items.map(i=>`<button role="menuitem" data-action="context" data-args="${E(i.action)}" ${i.disabled?'disabled':''}>${E(i.label)}</button>`).join('')}</div>`;const box=host.firstElementChild;box.style.left=Math.max(4,Math.min(e.clientX,innerWidth-box.offsetWidth-4))+'px';box.style.top=Math.max(4,Math.min(e.clientY,innerHeight-box.offsetHeight-4))+'px'}
let contextData=null;
function contextFor(e,scope,row){const chosen=rowsSelected(scope),no=!chosen.length;contextData={scope,row,rows:chosen};const names=scope==='faces'?['轨迹','伴随','布控','位置追踪']:['复制','统计','轨迹','伴随','检索','布控','位置追踪','区域统计','添加数据集'];contextMenu(e,names.map(label=>({label,action:label,disabled:['区域统计','添加数据集'].includes(label)?!no:(scope==='faces'&&label!=='位置追踪'?false:no)||(label==='伴随'&&new Set(chosen.map(r=>r.target)).size>1)})))}
async function dataAction(action,rows){if(!rows?.length){toast('请先勾选数据',true);return}const targets=[...new Set(rows.map(r=>r.target))],type=rows[0].type||'电围';if(action==='复制'){const text=targets.join('\n');try{await navigator.clipboard.writeText(text);toast('已复制 '+targets.length+' 个目标')}catch{modal('复制数据',`<textarea class="wide" readonly>${E(text)}</textarea><p>浏览器未授予剪贴板权限，可在此选择复制。</p>`)}return}if(action==='统计'){ps().stats=statsFor(rows);ps().selected.stats=[];render();return}if(action==='检索'){const name={'电围':'围栏检索','车牌':'车牌检索','MAC':'MAC检索','人像':'人像检索'}[type];if(active!==name)show(name);ps().filters.target=targets.join(',');ps().selected.captures=[];render();return}if(action==='轨迹'||action==='位置追踪'){show('地图研判',{resetFilters:true,target:targets.join(','),filters:{type},trajectory:true});return}if(action==='伴随'){if(targets.length!==1){toast('伴随分析仅支持单目标',true);return}analysisForm('伴随任务',null,db.captures.filter(c=>c.type===type&&targets.includes(c.target)));return}if(action==='布控'){watchForm(null,rows);return}}
const chartSnapshots={};
function lineChart(id,labels=['系列'],count=7,scale=1,source=null){if(source)count=source.length;
 const hidden=ps().chart[id]||[], colors=['#1769aa','#20a47c','#e69b31','#a570b8','#bd495e'];
 const dates=source?source.map(r=>r.日期):Array.from({length:count},(_,j)=>{const d=new Date(day+'T12:00:00');if(count===12)d.setMonth(d.getMonth()-(count-1-j));else d.setDate(d.getDate()-(count-1-j));return d.toISOString().slice(0,count===12?7:10)});
 const series=labels.map((label,i)=>({label,values:source?source.map(r=>Number(r[label])||0):dates.map((_,j)=>(40+(j*13+i*19)%90)*scale)}));chartSnapshots[id]=dates.map((date,j)=>Object.fromEntries([['日期',date],...series.map(s=>[s.label,s.values[j]])]));const max=Math.max(1,...series.flatMap(s=>s.values));
 return `<div class="chart-legend">${labels.map((l,i)=>`<button type="button" class="link ${hidden.includes(l)?'off':''}" style="color:${colors[i%5]}" data-action="chart-toggle" data-args="${id}|${l}">${E(l)}</button>`).join('')}</div><svg class="line-chart" viewBox="0 0 340 150" role="img" aria-label="${E(id)}"><path d="M25 10V125H330 M25 40H330 M25 80H330" fill="none" stroke="#dbe4eb"/><text x="0" y="15" font-size="9" fill="#5e6d7c">${max}</text>${series.map((s,i)=>hidden.includes(s.label)?'':`<polyline fill="none" stroke="${colors[i%5]}" stroke-width="2" points="${s.values.map((v,j)=>`${25+j*300/(count-1)},${125-v/max*110}`).join(' ')}"/>${s.values.map((v,j)=>`<circle cx="${25+j*300/(count-1)}" cy="${125-v/max*110}" r="3" fill="${colors[i%5]}"><title>${dates[j]} · ${E(s.label)}：${v} 条/台/次</title></circle>`).join('')}`).join('')}</svg><div class="chart-labels"><span>${dates[0]}</span><span>日期 / 数量 · Mock</span><span>${dates.at(-1)}</span></div>`
}
function homeMap(){return `<div class="overview-map">${db.sites.map((s,i)=>`<button class="region" style="left:${6+i%3*30}%;top:${12+Math.floor(i/3)*48}%" data-region="${E(s.region)}" data-action="home-region" data-args="${E(s.region)}">${E(s.region)}</button>`).join('')}<div id="map-tip" class="map-tip hide"></div></div>`}
function dashboard(){const f=ps().filters;return `<div class="dashboard-layout"><div class="stack">${card('设备在线数量',`<div class="stats-list">${['低功率','中功率','高功率'].map((p,i)=>{const ds=db.devices.filter(d=>(Number(d.params.power)<15?0:Number(d.params.power)<25?1:2)===i);return `<div class="stat">${p}<b>${ds.length} 台 · 在线率 ${ds.length?Math.round(ds.filter(d=>d.status==='在线').length/ds.length*100):0}%</b></div>`}).join('')}</div>`)}${card('近7天采集数据',lineChart('home-seven',types.slice(0,3)))}${card('采集场所前五排行',`<label>设备类型<select data-home="rankType">${types.slice(0,3).map(t=>`<option ${f.rankType===t?'selected':''}>${t}</option>`).join('')}</select></label><ol>${[...db.sites].sort((a,b)=>a.name.localeCompare(b.name)*(f.rankType==='车牌'?-1:1)).map((s,i)=>`<li>${s.name} · ${(5-i)*130+(types.indexOf(f.rankType||'电围')*37)} 条</li>`).join('')}</ol>`)}</div><div class="stack">${card('当日采集 / 累计采集',`<div class="row"><div><div class="meta">当日采集（尚未全部入库）</div><div class="metric" id="today-count">12,480</div></div><div><div class="meta">累计采集</div><div class="metric">12,800,000</div></div></div><p class="hint" id="home-update">更新时间 ${new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai'})} · 定时更新</p>`)}<div class="two-column"><div class="stack">${card('设备累计采集（已入库）',types.slice(0,3).map((t,i)=>`<div class="stat">${t}<b>${(i+1)*123000} 条</b></div>`).join(''))}${card('设备布控告警次数',db.devices.slice(0,4).map((d,i)=>`<div class="stat">${d.name}<b>${i+1} 次</b></div>`).join(''))}</div>${card('设备分布',homeMap())}</div>${card('一周去重后采集数据',`<label>设备类型<select data-home="dedupType">${types.slice(0,3).map(t=>`<option ${f.dedupType===t?'selected':''}>${t}</option>`).join('')}</select></label><label>数据分类<select data-home="dedupClass">${['日采集卡码量','省外日采集卡码量','境外日采集卡码量'].map(t=>`<option ${f.dedupClass===t?'selected':''}>${t}</option>`).join('')}</select></label>${lineChart('home-dedup',[f.dedupClass||'日采集卡码量'],7,(types.indexOf(f.dedupType||'电围')+1)*(['日采集卡码量','省外日采集卡码量','境外日采集卡码量'].indexOf(f.dedupClass||'日采集卡码量')+1))}`)}${card('数据归属地前十位排行',`<div class="row">${Array.from({length:10},(_,i)=>`<span>${i+1}. 示例地区${i+1} · ${1000-i*70}</span>`).join('')}</div>`)}</div><div class="stack">${card('应用入口',`<div class="actions">${[['数据检索','围栏检索'],['数据研判','伴随任务'],['综合分析','地图研判'],['布控预警','综合布控']].map(([l,n])=>B(l,'nav',n)).join('')}</div>`)}${card('电围分类统计',`<div class="row">近一个月<div class="right-actions">${B('下载报表','chart-export','电围分类统计','small')}</div></div>${lineChart('home-fence',['2G','4G','5G'],30)}`)}${card('一周操作统计',lineChart('home-actions',['数据查询','数据分析','运维操作']))}</div></div>`}
function mapDevices(){const allowed=db.devices.filter(d=>superuser()||role().sites.includes(d.site));const f=ps().filters;return filters(allowed,{site:'site',status:'status',keyword:d=>d.name+' '+d.serial,region:'region'}).filter(d=>!f.sites?.length||f.sites.includes(d.site)).filter(d=>!f.devices?.length||f.devices.includes(d.id))}
function mapResults(){return searchRows(ps().filters.type==='综合'?undefined:ps().filters.type||'电围').sort((a,b)=>a.time.localeCompare(b.time))}
function mapPage(distribution=false){const devs=mapDevices(),results=mapResults(),picked=devs.filter(d=>mapState.selected.includes(d.id));let fields=distribution?[['status','在线状态',['全部','在线','离线']],['keyword','设备关键字']]:[['type','数据类型',[...types,'综合']],['site','场所',selectSites()],['start','采集开始',null,'datetime-local'],['end','采集结束',null,'datetime-local'],['target','IMSI / 车牌 / MAC / 人像'],['imei','IMEI']];
 const control=controls(fields,'搜索',`${B('框选','map-tool','box',mapState.tool==='box'?'active':'')}${B(distribution?'手动选择':'单选','map-tool','single',mapState.tool==='single'?'active':'')}${B('重置地图','map-reset')}`);
 const target=results[0],person=target&&db.people.find(p=>p.id===target.person),trajectory=mapState.trajectory&&results.length;const points=results.map(c=>db.devices.find(d=>d.id===c.deviceId)).filter(Boolean);
 const map=`<div class="map" id="map-canvas"><div class="map-world" style="transform:scale(${mapState.zoom})">${mapState.heat?devs.map(d=>`<div class="heat" style="left:${d.x}%;top:${d.y}%;opacity:${d.count/3400}"></div>`).join(''):''}${trajectory?`<svg viewBox="0 0 100 100" preserveAspectRatio="none"><polyline data-trajectory points="${points.map(d=>`${d.x},${d.y}`).join(' ')}" fill="none" stroke="#df8240" stroke-width=".7" stroke-dasharray="2 1"/></svg>`:''}${distribution&&mapState.zoom===1?db.sites.filter(s=>devs.some(d=>d.region===s.region)).map((s,i)=>`<button class="dot aggregate" data-action="map-cluster" data-args="${E(s.region)}" style="left:${15+i*17}%;top:12%;background:#438870" title="${E(s.region)}聚合设备，点击放大">${devs.filter(d=>d.region===s.region).length}</button>`).join(''):''}${devs.map((d,i)=>`<button class="dot ${d.status==='离线'?'offline':''} ${mapState.selected.includes(d.id)?'selected':''}" data-device-point="${d.id}" data-action="map-point" data-args="${d.id}" style="left:${d.x}%;top:${d.y}%" title="${E(d.name+' · '+d.site+' · '+d.status)}">${i+1}</button>`).join('')}</div><div class="map-tools">${B('+','map-zoom','0.25','small')}${B('−','map-zoom','-0.25','small')}${B('图层','map-layer','','small')}${B('热力图','map-heat','',mapState.heat?'active small':'small')}</div><div class="map-label">${E(mapState.layer)} · 缩放 ${mapState.zoom.toFixed(2)} · ${trajectory?'橙色线：目标轨迹 · ':''}${mapState.heat?'颜色越深表示采集量越大':'蓝色：在线设备 · 灰色：离线设备'}<br>操作模式：${mapState.tool==='box'?'按下并拖动鼠标框选设备':'单击设备'}</div></div>`;
 const right=card('已选设备',`<div class="stats-list">${picked.map(d=>`<div class="stat">${L(d.name,'device-info',d.id)}<p>${E(d.site)} · ${E(d.status)}</p></div>`).join('')||'<p class="hint">请框选或单选地图设备</p>'}</div>${distribution?`<div class="actions">${B('场所详情','map-sites','', '',!picked.length)}${B('设备详情','map-devices','','',!picked.length)}</div>`:`<div class="actions">${B('区域统计','map-analysis','区域统计','',!picked.length)}${B('伴随分析','map-analysis','伴随任务','',!picked.length)}</div>`}`)+(!distribution&&person?card('目标基本信息',`<div class="detail-panel"><img class="target-photo" src="${E(person.image)}" alt="人物画像"><dl>${[['姓名',person.name],['性别',person.sex],['民族',person.ethnic],['手机号码',person.phone],['身份证号码',person.identity],['常驻地区',person.resident],['疑似落脚点',person.landing],['被设备捕捉次数',results.filter(c=>c.person===person.id).length],['经过站点次数',new Set(results.filter(c=>c.person===person.id).map(c=>c.site)).size],['经过区域', [...new Set(results.filter(c=>c.person===person.id).map(c=>c.region))].join('、')]].map(([l,v])=>`<dt>${l}</dt><dd>${E(v)}</dd>`).join('')}</dl></div>`):'');
 return (distribution?card('场所与设备选择',`<h3>场所</h3>${checkFields('map-sites',visibleSites().map(s=>s.name),ps().filters.sites||[])}<h3 style="margin-top:12px">设备</h3>${checkFields('map-query-devices',db.devices.filter(d=>superuser()||role().sites.includes(d.site)).map(d=>({value:d.id,label:d.name})),ps().filters.devices||[])}`):'')+control+`<div class="query-split"><div class="stack">${map}${distribution?card('区域设备在线率',`<div class="rate-chart" role="img" aria-label="设备在线率统计图">`+db.sites.map(s=>{const ds=devs.filter(d=>d.site===s.name);const rate=ds.length?Math.round(ds.filter(d=>d.status==='在线').length/ds.length*100):0;return `<div class="stat">${s.region}<b>${rate}% (${ds.filter(d=>d.status==='在线').length}/${ds.length})</b></div><div class="rate-bar"><span style="width:${rate}%"></span></div>`}).join('')+'</div>'):captureTable('map-results',results,B('展示轨迹','map-trajectory'),[])}</div><aside class="stack">${right}</aside></div>`+(trajectory?card('轨迹时间轴',`<label>播放进度 <input data-timeline type="range" min="0" max="${Math.max(0,results.length-1)}" value="0"><output id="timeline-output">${E(results[0]?.time||'')}</output></label><div id="timeline-point">${E(results[0]?.site||'')}</div>`):'')}
function analysisForm(kind,id,rows=[]){const old=db.analysis[kind]?.find(t=>t.id===id),record=old||{name:'',target:rows[0]?.target||'',start:rows.length?rows.map(r=>r.time).sort()[0].replace(' ','T'):day+'T08:00',end:rows.length?rows.map(r=>r.time).sort().at(-1).replace(' ','T'):day+'T18:00',regions:[...new Set(rows.map(c=>c.region))],sites:[...new Set(rows.map(c=>c.site))],threshold:60};const body=`<div class="form-grid">${field('name','任务名称',record.name,null,'text',true)}${field('target','目标标识（伴随为单目标）',record.target,null,'text',kind==='伴随任务')}${field('start','分析开始时间',record.start,null,'datetime-local',true)}${field('end','分析结束时间',record.end,null,'datetime-local',true)}${field('threshold','最低关联度 / 匹配度（%）',record.threshold,null,'number',true)}<div><label>任务选区</label>${checkFields('regions',db.sites.map(s=>s.region),record.regions)}</div><div class="wide"><label>场所</label>${checkFields('sites',visibleSites().map(s=>s.name),record.sites)}</div>${rows.length?`<div class="wide"><h3>从检索带入的时空信息</h3><ul>${rows.map(r=>`<li>${E(r.target)} · ${E(r.time)} · ${E(r.site)}</li>`).join('')}</ul></div>`:''}</div>`;modal((old?'编辑':'新增')+kind.replace('任务','分析'),body,f=>{if(f.get('start')>f.get('end'))throw Error('结束时间应晚于开始时间');if(!f.getAll('regions').length)throw Error('请至少选择一个任务选区');if(Number(f.get('threshold'))<0||Number(f.get('threshold'))>100)throw Error('阈值范围为0到100');const r={id:old?.id||uid('T'),name:f.get('name'),target:f.get('target'),start:f.get('start'),end:f.get('end'),regions:f.getAll('regions'),sites:f.getAll('sites'),threshold:Number(f.get('threshold')),date:day,status:'成功',account:user().account,sourceIds:rows.map(r=>r.id)};if(old)Object.assign(old,r);else db.analysis[kind].push(r);save();closeModal();if(!old){show(kind);ps().filters={};}detail=null;render();toast('任务已保存，Mock分析完成')})}
function analysisResult(task,type){const all=captureRows(type);const targetSet=[...new Set(all.map(r=>r.target))];return targetSet.slice(0,6).map((target,i)=>{const matched=all.filter(c=>c.target===target&&(!task.sites.length||task.sites.includes(c.site))&&c.time.replace(' ','T')>=task.start&&c.time.replace(' ','T')<=task.end);const visited=[...new Set(matched.map(c=>c.region))].filter(r=>task.regions.includes(r));const score=active==='区域统计'?Math.round(visited.length/Math.max(1,task.regions.length)*100):Math.max(0,100-i*13);return {id:target,type,target,count:matched.length,stations:new Set(matched.map(c=>c.site)).size,visited,score,first:matched[0]?.time||'',captures:matched}}).filter(r=>r.count&&r.score>=task.threshold)}
function taskPage(){if(detail?.kind==='analysis'){const t=db.analysis[active].find(t=>t.id===detail.id);if(!t){detail=null;return taskPage()}const ts=active==='区域统计'?types.filter(t=>t!=='人像'):types;const tab=ts.includes(ps().tab)?ps().tab:ts[0],rows=analysisResult(t,tab);return card(t.name,`<div class="row toolbar">${B('任务编辑','edit-analysis',t.id)}<span>目标 ${E(t.target||'未知目标')} · ${E(t.start)} 至 ${E(t.end)}</span></div><p>任务选区：${E(t.regions.join('、'))} · ${active==='区域统计'?'匹配度 = 经过任务选区数 / 任务选区总数':'关联度 = Mock满足条件比例'} · 最低 ${t.threshold}%</p><div class="tabs">${ts.map(type=>B(type,'result-tab',type,type===tab?'active':'')).join('')}</div>`)+table('analysis-results',['目标标识','采集总次数','经过站点','经过任务选区',active==='区域统计'?'匹配度':'关联度','二次操作'],rows,r=>[E(r.target),r.count,r.stations,E(r.visited.join('、')),r.score+'%'+(active==='区域统计'?` (${r.visited.length}/${t.regions.length})`:''),['检索','轨迹','伴随','布控'].map(a=>B(a,'result-action',r.id+'|'+a,'small')).join('')],true,'任务结果',B('导出','export-scope','analysis-results'))}
 const rows=filters(db.analysis[active],{name:'name',start:'start',end:'end'});return controls([['name','任务名称'],['start','分析开始',null,'date'],['end','分析结束',null,'date']])+`<div class="row toolbar">${B(active==='伴随任务'?'新增伴随分析':'新增','add-analysis','','primary')}${B('删除','delete-scope','analysis')}</div>`+table('analysis',[['任务名称','name'],'目标','分析开始','分析结束','状态'],rows,r=>[L(r.name,'analysis-detail',r.id),E(r.target||'区域未知目标'),E(r.start),E(r.end),'<span class="tag">'+E(r.status)+'</span>'],true,'任务列表',B('导出','export-analysis'))}
function libraryPage(){if(detail?.kind==='library'){const lib=db.libraries.find(l=>l.id===detail.id);if(!lib){detail=null;return libraryPage()}const people=db.people.filter(p=>lib.people.includes(p.id));return card(lib.name,`<div class="row">${B('编辑库信息','edit-library',lib.id)}${B('新增人员','add-person',lib.id)}</div>`)+table('people',['姓名','性别','手机','身份证','特征码','操作'],people,p=>[L(p.name,'person-info',p.id),p.sex,E(p.phone),E(p.identity),E(p.target),B('编辑','edit-person',lib.id+'|'+p.id,'small')+B('删除','delete-person',lib.id+'|'+p.id,'small')+B('布控','person-watch',p.id,'small')],true,'人员详情')}
 return controls([['name','库名'],['category','分类',['全部','重点人员','常驻人员','自建库']]])+`<div class="row toolbar">${B('新增','add-library','','primary')}${B('删除','delete-scope','libraries')}</div>`+table('libraries',['库名','分类','人员数量'],filters(db.libraries,{name:'name',category:'category'}),l=>[L(l.name,'library-detail',l.id),E(l.category),l.people.length],true,'人员库',B('导入','import-libraries')+B('导出','export-libraries'))}
function libraryForm(id){const lib=db.libraries.find(l=>l.id===id);modal(lib?'编辑人员库':'新增人员库',`<div class="form-grid">${field('name','库名',lib?.name||'',null,'text',true)}${field('category','分类',lib?.category||'自建库',['重点人员','常驻人员','自建库'])}</div>`,f=>{if(db.libraries.some(l=>l.name===f.get('name')&&l.id!==id))throw Error('库名已存在');if(lib)Object.assign(lib,{name:f.get('name'),category:f.get('category')});else db.libraries.push({id:uid('LIB'),name:f.get('name'),category:f.get('category'),people:[]});save();closeModal();render();toast('人员库已保存')})}
