function setEvaluate(expression,sets){const tokens=expression.replace(/\s/g,'').match(/[A-Z]|[()∩∪−-]/g)||[];if(tokens.join('')!==expression.replace(/\s/g,''))throw Error('表达式只允许集合字母、括号和∩∪−');let p=0;function atom(){let t=tokens[p++];if(t==='('){const r=expr();if(tokens[p++]!==')')throw Error('括号不匹配');return r}const idx=t?.charCodeAt(0)-65;if(!sets[idx])throw Error('表达式引用未拖入的数据集');return new Set(sets[idx])}function expr(){let a=atom();while(p<tokens.length&&tokens[p]!==')'){const op=tokens[p++],b=atom();a=op==='∪'?new Set([...a,...b]):op==='∩'?new Set([...a].filter(x=>b.has(x))):new Set([...a].filter(x=>!b.has(x)))}return a}const result=expr();if(p!==tokens.length)throw Error('表达式不完整');return [...result]}
