function importDialog(title,apply,sample=[]){let parsed=null;modal(title,`<label>选择文件<input name="importFile" type="file" accept=".xlsx,.csv,.json" required></label><p class="hint">支持Excel .xlsx、CSV、JSON。列名与导出文件一致；读入预览后点击确定才更新数据。</p>${sample.length?B('下载导入模板','import-template'):''}<div id="import-preview" class="status-bar">尚未读取文件</div>`,async()=>{if(!parsed?.length)throw Error('请选择包含有效数据的文件');const original=structuredClone(db);try{await apply(parsed)}catch(error){db=original;save();throw error}save();closeModal();render();toast('已导入 '+parsed.length+' 条数据')},'确定');importHandler={applyParsed:rows=>{parsed=rows},sample}}
function importDataset(){importDialog('导入数据集',rows=>{const items=[];for(const row of rows){if(!row.target)throw Error('缺少target列');let c=db.captures.find(c=>c.id===row.id||c.target===row.target&&c.time===row.time);if(!c){c={...row,id:uid('C'),type:row.type||'电围',site:row.site||db.sites[0].name,region:row.region||db.sites[0].region,device:row.device||db.devices[0].name,deviceId:row.deviceId||db.devices[0].id,time:row.time||day+' 10:00:00',imei:row.imei||'',score:Number(row.score)||100,person:row.person||'P0'};db.captures.push(c)}items.push(c.id)}db.datasets.push({id:uid('SET'),name:'导入数据集 '+(db.datasets.length+1),items:[...new Set(items)]})},[db.captures[0]])}
function importLibraries(){importDialog('导入人员库',rows=>{for(const row of rows){if(!row.name||!row.category)throw Error('必须包含name库名与category分类列');let lib=db.libraries.find(l=>l.name===row.name);if(!lib){lib={id:uid('LIB'),name:row.name,category:row.category,people:[]};db.libraries.push(lib)}if(row.personName&&row.target){let p=db.people.find(p=>p.target===row.target);if(!p){p={id:uid('P'),name:row.personName,target:row.target,sex:row.sex||'',ethnic:row.ethnic||'',phone:row.phone||'',identity:row.identity||'',resident:row.resident||'',landing:row.landing||'',image:portrait(db.people.length)};db.people.push(p)}if(!lib.people.includes(p.id))lib.people.push(p.id)}}},[{name:'导入示例库',category:'自建库',personName:'虚构人员',target:'460000000009999',phone:'13800000009'}])}
