document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b){if(!e.target.closest('.context-menu'))closeContext();return}try{const a=b.dataset.action;if(a!=='context')closeContext();if(!['login','logout','close-modal','state','messages'].includes(a))log('操作 '+b.textContent.trim());await handle(a,b.dataset.args||'',b)}catch(err){toast(err.message,true)}});
document.addEventListener('submit',async e=>{if(e.target.getAttribute('id')==='query-form'){e.preventDefault();const current=active;Object.assign(ps().filters,Object.fromEntries(new FormData(e.target)));if(ps().filters.start&&ps().filters.end&&ps().filters.start>ps().filters.end){toast('开始时间不能晚于结束时间',true);return}ps().selected={};ps().page={};ps().mode='loading';log('查询 '+active);render();setTimeout(()=>{if(active===current){ps().mode='data';if(active==='地图研判')mapState.trajectory=true;render();toast('查询完成')}},180)}if(e.target.getAttribute('id')==='modal-form'){e.preventDefault();try{await modalSave?.(new FormData(e.target));log('保存表单 '+active)}catch(err){formError(err.message)}}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.matches('[data-select]')){const s=el.dataset.select,list=selected(s);ps().selected[s]=el.checked?[...new Set([...list,el.value])]:list.filter(x=>x!==el.value);render();return}if(el.matches('[data-select-all]')){const s=el.dataset.selectAll;ps().selected[s]=el.checked?(scopes[s]||[]).map(r=>r.id):[];render();return}if(el.matches('[data-limit]')){ps().limit=Number(el.value);ps().page={};render();return}
 if(el.id==='identity'){session=el.value;detail=null;history=[];pageStates={};mapState.selected=[];log('切换演示身份');render();return}if(el.matches('[data-home]')){ps().filters[el.dataset.home]=el.value;render();return}if(el.name==='map-query-devices'){ps().filters.devices=[...document.querySelectorAll('[name="map-query-devices"]:checked')].map(x=>x.value);mapState.selected=[];render();return}if(el.name==='map-sites'){ps().filters.sites=[...document.querySelectorAll('[name="map-sites"]:checked')].map(x=>x.value);mapState.selected=[];render();return}if(el.name?.startsWith('ops')){ps().filters[el.name]=el.value;render();return}
 if(el.id==='face-file'){const file=el.files[0];if(!file)return;if(!file.type.startsWith('image/'))throw Error('请选择图片文件');const reader=new FileReader();reader.onload=()=>{faceSource=reader.result;faceReference=0;ps().selected.faces=[];ps().filters.similarity=0;render();toast('已自动搜图，展示Mock相似结果')};reader.readAsDataURL(file);return}
 if(el.name==='person'&&el.closest('#modal-form')){const p=db.people.find(p=>p.id===el.value);if(p)document.querySelector('#modal-form [name="target"]').value=p.target;return}
 if(el.name==='region'&&el.closest('#modal-form')&&document.querySelector('.steps')){wizard.name=document.querySelector('#modal-form [name="name"]').value;wizard.region=el.value;wizard.group=db.devices.find(d=>d.region===el.value)?.group||'';const group=document.querySelector('#modal-form [name="group"]');group.innerHTML=[...new Set(db.devices.filter(d=>d.region===el.value).map(d=>d.group))].map(g=>`<option>${E(g)}</option>`).join('');return}
 if(['mode','type'].includes(el.name)&&document.getElementById('multi-report-types')){const f=document.getElementById('modal-form'),multi=f.elements.mode.value==='多报表';document.getElementById('multi-report-types').classList.toggle('hide',!multi);f.elements.type.closest('label').classList.toggle('hide',multi);f.elements.subtype.closest('label').classList.toggle('hide',multi);const opts=f.elements.type.value==='设备报表'?reportTypes().slice(0,2):f.elements.type.value==='数据报表'?reportTypes().slice(2,7):reportTypes().slice(7);f.elements.subtype.innerHTML=opts.map(s=>`<option>${E(s)}</option>`).join('');return}
 if(el.name==='importFile'){const rows=await readImport(el.files[0]);if(!Array.isArray(rows))throw Error('导入内容必须是记录数组');importHandler.applyParsed(rows);document.getElementById('import-preview').textContent=`已读取 ${rows.length} 条。首条：${JSON.stringify(rows[0]||{})}`;return}
 }catch(err){if(document.getElementById('form-error'))formError('读取失败：'+err.message);else toast(err.message,true)}});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-similarity]')){ps().filters.similarity=Number(el.value);render()}if(el.matches('[data-timeline]')){const rows=mapResults(),row=rows[Number(el.value)];document.getElementById('timeline-output').textContent=row?.time||'';document.getElementById('timeline-point').textContent=row?.site||'';const id=row?.deviceId;document.querySelectorAll('[data-device-point]').forEach(b=>b.classList.toggle('selected',b.dataset.devicePoint===id))}});
document.addEventListener('contextmenu',e=>{closeContext();const face=e.target.closest('[data-face]'),row=e.target.closest('tr[data-row-id]');if(face){contextFor(e,'faces',db.captures.find(c=>c.id===face.dataset.face));return}if(row&&['captures','map-results','dataset-results','profile-results'].includes(row.dataset.scope)){contextFor(e,row.dataset.scope,scopes[row.dataset.scope].find(r=>r.id===row.dataset.rowId));return}const point=e.target.closest('[data-device-point]');if(point){contextData={device:point.dataset.devicePoint};contextMenu(e,[{label:'设备详情',action:'设备详情'},{label:'场所详情',action:'场所详情'}]);return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('.context-menu'))closeContext();else closeModal()}if(e.key==='Tab'&&document.querySelector('.modal')){const items=[...document.querySelector('.modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea')].filter(x=>x.offsetParent);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
let regionTimer;document.addEventListener('mouseover',e=>{const region=e.target.closest('[data-region]');if(region&&!region.contains(e.relatedTarget)){clearTimeout(regionTimer);regionTimer=setTimeout(()=>{const tip=document.getElementById('map-tip');if(!tip)return;const ds=db.devices.filter(d=>d.region===region.dataset.region);tip.innerHTML=E(region.dataset.region)+'<br>'+types.map(t=>`${t} ${ds.filter(d=>d.type===t).length} 台`).join(' · ');tip.classList.remove('hide')},1000)}});document.addEventListener('mouseout',e=>{if(e.target.closest('[data-region]')&&!e.target.closest('[data-region]').contains(e.relatedTarget)){clearTimeout(regionTimer);document.getElementById('map-tip')?.classList.add('hide')}});
let boxDrag=null;document.addEventListener('pointerdown',e=>{const canvas=e.target.closest('#map-canvas');if(!canvas||mapState.tool!=='box'||e.target.closest('.map-tools')||e.button!==0)return;e.preventDefault();closeContext();const r=canvas.getBoundingClientRect();boxDrag={canvas,x:e.clientX,y:e.clientY,rect:r};const box=document.createElement('div');box.className='selection-box';canvas.append(box);boxDrag.box=box;canvas.setPointerCapture(e.pointerId)});document.addEventListener('pointermove',e=>{if(!boxDrag)return;const d=boxDrag,x=Math.min(d.x,e.clientX)-d.rect.left,y=Math.min(d.y,e.clientY)-d.rect.top;Object.assign(d.box.style,{left:x+'px',top:y+'px',width:Math.abs(e.clientX-d.x)+'px',height:Math.abs(e.clientY-d.y)+'px'})});document.addEventListener('pointerup',e=>{if(!boxDrag)return;const d=boxDrag;mapState.selected=[...d.canvas.querySelectorAll('[data-device-point]')].filter(b=>{const r=b.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2;return x>=Math.min(d.x,e.clientX)&&x<=Math.max(d.x,e.clientX)&&y>=Math.min(d.y,e.clientY)&&y<=Math.max(d.y,e.clientY)}).map(b=>b.dataset.devicePoint);boxDrag=null;render();toast('已框选 '+mapState.selected.length+' 台设备')});
document.addEventListener('dragstart',e=>{const ds=e.target.closest('[data-dataset]');if(ds)e.dataTransfer.setData('text/plain',ds.dataset.dataset)});document.addEventListener('dragover',e=>{const zone=e.target.closest('[data-dropzone]');if(zone){e.preventDefault();zone.classList.add('dragover')}});document.addEventListener('dragleave',e=>e.target.closest('[data-dropzone]')?.classList.remove('dragover'));document.addEventListener('drop',e=>{const zone=e.target.closest('[data-dropzone]');if(!zone)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(db.datasets.some(d=>d.id===id))operands.push(id);render()});
setInterval(()=>{const now=new Date().toLocaleTimeString('sv-SE',{timeZone:'Asia/Shanghai'}).slice(0,5),today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});db.notifications.filter(n=>n.status==='执行中'&&n.time<=now&&!n.last.startsWith(today)).forEach(sendNotification);const update=document.getElementById('home-update');if(update){update.textContent='更新时间 '+now+' · 定时更新';document.getElementById('today-count').textContent=(12480+db.logs.length).toLocaleString()}},10000);
window.addEventListener('scroll',closeContext,true);
